/* =====================================================================
   figures-original.js — the diagrams Ball supplied, embedded as PNG.
   Kept as data URIs so the app works from any origin and the canvas
   export never taints. Loaded after figures.js and merged into the
   same FIGURES registry.
   ===================================================================== */

(function (global) {
  'use strict';

  var ORIGINALS = {
  /* the colon Ball drew on for the operative note: the whole large bowel
     with its arterial and venous supply, so a resection can be marked on
     the vessels as well as on the bowel. It replaces the older colon
     outline as the sheet a colorectal case opens on; that one stays in
     the Add-figure picker. */
  orig_colon_vessels: { th: 'ลำไส้ใหญ่และหลอดเลือด', en: 'Colon with blood supply',
    w: 800, h: 1160,
    png: 'data:image/png;base64,' },
  orig_colon: { th: 'ลำไส้ใหญ่ (ภาพต้นฉบับ)', en: 'Colon — original diagram', w: 736, h: 641,
    png: 'data:image/png;base64,' },
  orig_anal_clock: { short: 'Axial', th: 'ทวารหนัก ภาพตัดขวาง', en: 'Anal canal — axial (A/P/Rt/Lt)', w: 780, h: 738,
    png: 'data:image/png;base64,' },
  orig_anal_coronal: { short: 'Coronal', th: 'หูรูดทวารหนัก ภาพตัดแนวหน้า', en: 'Anal sphincters — coronal', w: 864, h: 682,
    png: 'data:image/png;base64,' },
  orig_anal_tract: { short: 'Tract', th: 'ทางเดินของฝีคัณฑสูตร', en: 'Fistula tract — coronal variant', w: 790, h: 636,
    png: 'data:image/png;base64,' }
  };

  /* rebuild the registry with the originals first so they head the picker */
  var merged = {};
  Object.keys(ORIGINALS).forEach(function (k) { merged[k] = ORIGINALS[k]; });
  Object.keys(global.FIGURES).forEach(function (k) { merged[k] = global.FIGURES[k]; });
  global.FIGURES = merged;

  /* originals open first for each category; the drawn vector versions
     stay available in the “Add figure” picker */
  global.FIGURE_DEFAULTS = {
    /* the abdominal wall sheet is still in the Add figure picker, it just
       no longer opens by default on every colorectal case */
    colorectal: ['orig_colon_vessels'],
    fistula: ['orig_anal_clock', 'orig_anal_coronal', 'orig_anal_tract'],
    hemorrhoid: ['orig_anal_clock'],
    others: ['blank']
  };

})(window);
